```javascript
/**
 * Finds the second largest number in an array of integers
 * Optimization: Only one pass through the array is needed
 * so time complexity is O(n) instead of O(n log n) with sorting.
 * 
 * @param {number[]} arr - input array of integers
 * @returns {number} - the second largest number in the array
 */
function secondLargest(arr) {
    // Return undefined if array length is less than 2 since a second largest does not exist
    if (arr.length < 2) return undefined;

    // Initialize two variables to track the largest and second largest numbers
    // Use -Infinity to cover arrays with negative numbers
    let largest = -Infinity;
    let secondLargest = -Infinity;

    for (let num of arr) {
        // Update largest and secondLargest accordingly
        if (num > largest) {
            // Current number is greater than largest found so far
            // secondLargest becomes previous largest
            secondLargest = largest;
            largest = num;
        } else if (num > secondLargest && num < largest) {
            // Current number is between largest and secondLargest
            secondLargest = num;
        }
    }

    // If secondLargest is still -Infinity, it means no second largest found
    // Possible when all elements are equal
    return secondLargest === -Infinity ? undefined : secondLargest;
}
```

Explanation:

- The code traverses the array once keeping track of the largest and second largest numbers found so far.
- This avoids sorting and achieves linear time complexity.
- The use of -Infinity ensures it works for arrays containing negative integers.
- The function returns undefined if no second largest number exists (e.g., array with one element or all elements equal).
- This approach is more efficient and correct compared to the original code.

