def extract_nav_missions(mission_str):
    result = []
    # Split the string by comma and strip spaces
    codes = [code.strip() for code in mission_str.split(',')]
    for code in codes:
        parts = code.split('-')
        # Expected format: OPERATION-XXXX-TYPE
        if len(parts) == 3:
            _, number_str, typ = parts
            if typ == 'NAV':
                try:
                    number = int(number_str)
                    if number > 2000:
                        result.append(code)
                except ValueError:
                    # Skip malformed numbers
                    continue
    return result
